-- ============================================================================
-- v129a: 语文[职高] L4知识点教学内容 Part1
-- 字音字形(8) + 词语运用(5) + 病句辨析与修辞(10) = 23个L4节点
-- 匹配方式：parent_id + name（幂等安全，UPDATE可重复执行）
-- ============================================================================

-- ============================================================
-- 字音字形（8个L4节点）parent: 字音字形(L3)
-- ============================================================

SET @l3_pinyin = (SELECT id FROM knowledge_nodes WHERE subject_id = 20 AND name = '字音字形' AND level = 3 LIMIT 1);

UPDATE knowledge_nodes SET content =
'【一句话定义】\n多音字指字形相同但有两个或以上读音的汉字，在不同词语中读音不同、意义不同。\n\n【具体说明】\n① 多音字类型：声韵不同（乐lè/yuè、长cháng/zhǎng）、声调不同（好hǎo/hào、为wéi/wèi）、声母不同（朝cháo/zhāo、降jiàng/xiáng）、韵母不同（还hái/huán）。\n② 高频多音字：差(chā差别/chà差不多/chāi出差/cī参差)、着(zhe看着/zháo着急/zhuó着落/zhāo高着)、强(qiáng强大/qiǎng勉强/jiàng倔强)、和(hé和平/hè应和/huó和面/hú和牌)。\n③ 记忆方法：组词记音法（在具体词语中记忆）、语境推断法（利用上下文区分）。\n\n【常见错误】\n1. 只记常用读音不记其他→"角"只知jiǎo不知jué（角色）\n2. 文白异读混用→"血"口语xiě、书面语xuè\n3. "薄"多音混淆→báo（薄饼）、bó（薄弱）、bò（薄荷）\n\n【考试方向】\n选择题选出"加点字读音全部正确"或"每对读音都相同/都不相同"的一项。'
WHERE parent_id = @l3_pinyin AND name = '多音字辨析';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n形近字指字形结构相似但意义和读音不同的汉字，容易混淆。\n\n【具体说明】\n① 形近字分类：声旁相同形旁不同（燥/躁/澡/藻、晦/悔/诲）、形旁相同声旁不同（腊/蜡/猎）、整体形近（己jǐ/已yǐ/巳sì、戊wù/戌xū/戍shù、未wèi/末mò、盲máng/肓huāng）、增减笔画（侯hóu/候hòu）。\n② 辨析技巧：形旁辨义法（月字旁多与身体有关、贝字旁多与钱财有关）、口诀记忆法（"己开已半巳全封""横戌点戍戊中空"）、语境识别法。\n③ 高频形近词组：辩/辨/辫/瓣、缜/慎、绽/淀/锭。\n\n【常见错误】\n1. "己/已/巳"→己(jǐ)出头、已(yǐ)半封、巳(sì)全封\n2. "侯/候"→侯(hóu)姓/诸侯，候(hòu)等候\n3. "燥/躁"→干燥用燥（火烤干），急躁用躁（跺脚急）\n\n【考试方向】\n选择题选出"下列词语中没有错别字的一项"。'
WHERE parent_id = @l3_pinyin AND name = '形近字辨析';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n易读错字指因口语习惯、字形干扰或方言影响而经常被读错的常用汉字。\n\n【具体说明】\n① 因口语习惯误读：气氛(fēn)非fèn、办公室(shì)非shǐ、比较(jiào)非jiǎo、召开(zhào)非zhāo、潜力(qián)非qiǎn、肖像(xiào)非xiāo、档次(dàng)非dǎng。\n② 因字形干扰（读半边）：莘莘学子(shēn)非xīn、酗酒(xù)非xiōng、臀部(tún)非diàn；受形近字影响：赡养(shàn)≠瞻仰(zhān)、侥幸(jiǎo)≠晓(xiǎo)、造诣(yì)≠旨(zhǐ)。\n③ 因方言干扰（四川方言重点）：平翘舌（竹zhú子≠zú子、吃chī饭≠cī饭）、鼻边音（牛niú奶≠流liú来、女nǚ生≠吕lǚ生）、前后鼻音（心xīn≠星xīng、门mén≠蒙méng）。\n\n【常见错误】\n1. 形声字一律读声旁→只有约25%的形声字声旁能准确表音\n2. 方言影响不自知→四川考生特别要注意平翘舌和前后鼻音\n3. 多音字只读第一反应→考试中常考查非首选读音\n\n【考试方向】\n选择题选出"加点字读音全部正确/有误的一项"。'
WHERE parent_id = @l3_pinyin AND name = '易读错字';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n易写错字指因字形相近、读音相同或书写习惯而经常写成别字的常用汉字。\n\n【具体说明】\n① 因形近致误："再接再厉"非"再接再励"（厉通砺，磨刀石）、"川流不息"非"穿流不息"（川指河流）、"一筹莫展"非"一愁莫展"（筹是计策）、"九霄云外"非"九宵云外"（霄雨字头与天气有关）。\n② 因音近致误："世外桃源"非"世外桃园"（陶渊明《桃花源记》）、"按部就班"非"按步就班"、"滥竽充数"非"烂鱼充数"（典出南郭处士吹竽）、"出其不意"非"出奇不意"。\n③ 因义近致误："人才辈出"非"人才倍出"（辈是一批批地）、"山清水秀"非"山青水秀"（清指清秀）。\n④ 增减笔画致误："武"右边无撇、"染"为氵+九+木非氵+丸+木。\n\n【常见错误】\n1. 成语中个别字写错→特别注意成语出处和本义\n2. 增减一点一横→戊(wù)戌(xū)戍(shù)戎(róng)四字细微差别\n\n【考试方向】\n选择题选出"下列词语中没有错别字/有错别字的一项"。'
WHERE parent_id = @l3_pinyin AND name = '易写错字';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n同音字指读音完全相同（声韵调全同）但意义和书写不同的汉字，正确区分同音字是减少别字的关键。\n\n【具体说明】\n① 高频同音字组：zuò（坐/座/做/作）→坐是动作、座是位子、做是手工、作是抽象；zài（在/再）→在表时空状态、再表重复；de（的/地/得）→的定语标志、地状语标志、得补语标志；yì（意/义/议/益）。\n② 辨析方法：偏旁辨义法（幕巾=幕布/暮日=日暮/墓土=坟墓/慕心=羡慕）、构词分析法（蓝蓝色/篮竹篮）、词性判断法（的+名词、地+动词、得+补充说明）。\n③ 特殊同音词组："必须"（副词）vs"必需"（动词）、"反映"（告诉上级/映射）vs"反应"（回应）、"启事"（公告）vs"启示"（启发）。\n\n【常见错误】\n1. "的/地/得"混用→最普遍的错别字问题\n2. "坐/座"→"请坐"用坐，"座位"用座\n3. "在/再"→"在干什么"用在，"再来一遍"用再\n\n【考试方向】\n选择题选出"下列词语中书写全部正确的一项"。'
WHERE parent_id = @l3_pinyin AND name = '同音字辨析';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n拼音拼写规则是汉语拼音方案规定的拼写规范，包括标调规则、隔音符号使用、ü的省略等内容。\n\n【具体说明】\n① 标调规则：声调标在主要元音（韵腹）上，口诀"有ɑ找ɑ，没ɑ找o、e；i、u并列标在后"。例：hǎo（有ɑ标ɑ）、hòu（有o标o）、xiù（i、u并列标在后）。\n② 隔音符号：以ɑ/o/e开头的音节连接在其他音节后面时用隔音符号隔开。例：Tiān''ānmén（天安门）、pí''ǎo（皮袄）、hǎi''ōu（海鸥）。\n③ ü的省略：j/q/x/y后面的ü去掉两点（jū居、qù去、xǔ许、yǔ雨）；n/l后面的ü保留两点（nǚ女、lǜ绿）。\n④ 其他规则：儿化音在音节末尾加r（huār花儿）、句子开头和人名地名首字母大写、轻声不标调号（māma妈妈）。\n\n【常见错误】\n1. i/u并列时标错→"秀xiù"标u上不是i上\n2. 该用隔音符号没用→"西安"Xī''ān不是Xiān\n3. j/q/x/y后ü仍带两点→常见干扰项\n\n【考试方向】\n选择题选出拼音完全正确的一项。'
WHERE parent_id = @l3_pinyin AND name = '拼音拼写规则';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n汉字结构知识包括汉字的造字方法（六书）、偏旁部首、间架结构等汉字学基础知识。\n\n【具体说明】\n① 造字方法：象形（日/月/山/水/人/木，描画实物形状）、指事（上/下/本/末/刃，加指示符号）、会意（休=人+木、明=日+月、从=两人）、形声（形旁表意+声旁表音，占汉字80%以上，如"江"氵形旁+工声旁）。\n② 偏旁部首：偏旁是合体字的组成部分，部首是字典归类依据。常见形旁含义：氵→水、火/灬→火、亻→人、女→女性、讠→语言、辶→走路、忄→心理、月→身体。\n③ 间架结构：独体字/合体字，左右结构/上下结构/包围结构。书写笔顺规则：先横后竖/先撇后捺/从上到下/从左到右/从外到内/先中间后两边。\n\n【常见错误】\n1. 形声字"读半边"→识别形声字局限性\n2. 部首与偏旁混淆→偏旁是结构概念，部首是查字法概念\n3. 笔顺错误→"火"笔顺是点、撇、撇、捺\n\n【考试方向】\n选择题：选出"属于形声字的一项"或"偏旁含义对应正确的一项"。'
WHERE parent_id = @l3_pinyin AND name = '汉字结构知识';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n四川方言辨正指针对四川方言与普通话在声母、韵母、声调方面的差异，进行系统的对比和纠正训练。\n\n【具体说明】\n① 声母辨正（三大问题）：平翘舌不分——z/c/s→zh/ch/sh混淆，"四(sì)是(shì)四，十(shí)是(shí)十"；鼻边音混淆——n→l容易混，"牛(niú)"≠"流(liú)"，"女(nǚ)"≠"吕(lǚ)"；h/f区分、r的发音。\n② 韵母辨正：前后鼻音不分——in≠ing（"心xīn"≠"星xīng"）、en≠eng（"门mén"≠"蒙méng"）、an≠ang（"单dān"≠"当dāng"）；e/o不分（"歌gē"≠"锅guō"）。\n③ 声调辨正：普通话阴平55/阳平35/上声214/去声51；四川话常用阳平代替普通话上声（"好hǎo"读成"háo"）；入声字遗留。\n④ 四川话特有词汇："你做啥子"→普通话"你做什么"；"晓得"→"知道"。\n\n【常见错误】\n1. 平翘舌凭感觉不查字典→养成查阅习惯\n2. 鼻边音自认为没问题→实际上n/l不分是四川人最普遍的语音缺陷\n3. 前后鼻音前鼻音过重→in和ing的区别主要在鼻腔共鸣位置\n\n【考试方向】\n选择题选出符合普通话标准的一项，题干混有方言干扰项。'
WHERE parent_id = @l3_pinyin AND name = '四川方言辨正';

SELECT 'v129a: 字音字形 8个L4节点完成' AS progress;

-- ============================================================
-- 词语运用（5个L4节点）parent: 词语运用(L3)
-- ============================================================

SET @l3_ciyu = (SELECT id FROM knowledge_nodes WHERE subject_id = 20 AND name = '词语运用' AND level = 3 LIMIT 1);

UPDATE knowledge_nodes SET content =
'【一句话定义】\n近义词辨析指从词义轻重、范围大小、搭配对象、感情色彩、语体色彩等维度区分意思相近的词语的差异。\n\n【具体说明】\n① 词义轻重：批评<批判、失望<绝望、损坏<毁坏、请求<恳求<哀求。\n② 范围大小：战争>战役>战斗、时代>时期>时间、边疆>边境。\n③ 搭配对象：提高（水平/能力/效率）+增强（体质/意识/信心）；改善（生活/条件）+改正（错误/缺点）；充足（具体·食物/阳光）vs充分（抽象·理由/准备）；严厉（态度/语气）vs严格（要求/标准）。\n④ 感情色彩：褒义（成果/鼓励/坚强/机智/义无反顾）；贬义（后果/怂恿/顽固/狡猾/一意孤行）；中性（结果/劝说/顽强/聪明/坚持己见）。\n⑤ 语体色彩：书面语（母亲/父亲/诞辰/配偶/部署）；口语（妈妈/爸爸/生日/对象/安排）。\n\n【常见错误】\n1. 搭配对象判断错误→"提高意识"（×），应为"增强意识"\n2. 感情色彩误判→褒义语境用贬义词\n3. 不看语体场合→日常口语用书面语词显得做作\n\n【考试方向】\n选择题：给四个句子，选出"加点词语使用恰当的一项"。'
WHERE parent_id = @l3_ciyu AND name = '近义词辨析';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n成语使用正误考查学生能否根据语境判断成语的使用是否恰当，包括含义准确、对象合适、色彩得体。\n\n【具体说明】\n① 望文生义类：首当其冲（最先受到攻击≠冲在前面）、差强人意（大体使人满意≠令人不满意）、不刊之论（不可更改的论断≠不可刊登）、万人空巷（家家户户人都出来了≠巷子没人了）。\n② 对象误用类：相敬如宾/举案齐眉（仅夫妻）、豆蔻年华（十三四岁少女）、美轮美奂（仅建筑）、汗牛充栋（仅藏书）、罄竹难书（仅罪恶）。\n③ 褒贬颠倒类：弹冠相庆（贬·同伙庆贺将做官）、趋之若鹜（贬·像鸭子跑去）、无所不为（贬·什么坏事都干）、处心积虑（贬·费尽心思干坏事）；殚精竭虑（褒·尽心尽力）。\n④ 谦敬错位类：蓬荜生辉（谦辞·使寒舍增辉）、鼎力相助（敬辞·请对方帮助）、抛砖引玉（谦辞·自己先发表粗浅意见）、不吝赐教（敬辞·请对方指教）。\n\n【常见错误】\n1. 记大意不记细节→不知适用对象和色彩\n2. 不看前后文→"差强人意的表现赢得了满堂喝彩"应为"精彩绝伦"\n3. 谦敬不分→"我一定鼎力相助"暴露不懂谦敬\n\n【考试方向】\n选出"加点成语使用恰当/不恰当的一项"。'
WHERE parent_id = @l3_ciyu AND name = '成语使用正误';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n关联词语是连接分句、表示逻辑关系的词语，正确搭配使用是语言准确性的重要体现。\n\n【具体说明】\n① 并列关系：既…又…、一边…一边…、不是…而是…（否定一方肯定另一方，与"不是…就是…"的选择关系区分）。\n② 递进关系：不但(不仅)…而且(还)…。主语相同时"不但"放主语后（他不但学习好，而且体育也好）；主语不同时放主语前（不但他学习好，而且他妹妹也好）。\n③ 转折关系：虽然(尽管)…但是(可是/却)…。"虽然…但是…"后一分句是主要意思。\n④ 因果关系：因为…所以…（客观因果）、既然…就…（推论因果，以已知事实为据）。\n⑤ 条件关系：只有…才…（必要条件·没它不行）、只要…就…（充分条件·有它就行）、无论…都…（无条件·任何条件结果不变）。\n⑥ 选择关系：不是…就是…、或者…或者…、与其…不如…、宁可…也不…。\n⑦ 假设关系：如果(假如)…就(那么)…（一般假设）、即使(就算)…也…（让步假设）。\n\n【常见错误】\n1. 关联词语搭配错乱→"虽然…所以…"应为"虽然…但是…"\n2. 主语位置错误→主语相同时"不但"应放主语后\n3. 逻辑关系判断错误→"既然…所以…"不成立\n\n【考试方向】\n选出"填入最恰当的一组关联词语"或病句题中关联词搭配错误的句子。'
WHERE parent_id = @l3_ciyu AND name = '关联词语搭配';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n词语的感情色彩指词语包含的褒贬态度，语体色彩指词语适用于书面语还是口语的风格差异。\n\n【具体说明】\n① 感情色彩三分法：褒义词（机智/执着/楷模·肯定赞许）、贬义词（狡猾/固执/嘴脸·否定贬斥）、中性词（聪明/坚持/样子·客观描述）。\n② 易混淆褒贬词组："后果"贬vs"成果"褒vs"结果"中性；"鼓动"中性vs"鼓励"褒vs"怂恿"贬；"保护"褒vs"庇护"贬；"理想"褒vs"幻想"贬vs"梦想"中性。\n③ 语体色彩：书面语（与会/莅临/部署/协商·用于庄重场合）、口语（来/搞/弄/商量·日常交流）。分辨原则：看场合（公文演讲用书面语，日常对话用口语）、看对象（对上级长者偏书面语）。\n④ 色彩转化（修辞需要）：褒词贬用（讽刺效果·"这位英雄可真是了不起啊"实际糟糕）；贬词褒用（亲昵效果·"这个''小坏蛋''"长辈对孩子的昵称）。\n\n【常见错误】\n1. 感情色彩判断错误→把贬义词当褒义词用\n2. 口语书面语混用→正式函件用"搞"太随意\n3. 忽视场合语体→演讲用"俺"（口语）、聊天用"吾"（文言）\n\n【考试方向】\n选出"加点词语感情色彩与其他不同的一项"或"用词最得体的一项"。'
WHERE parent_id = @l3_ciyu AND name = '词语的感情色彩与语体色彩';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n熟语是固定词组，包括惯用语（如"开夜车"）、谚语（如"瑞雪兆丰年"）、歇后语（如"外甥打灯笼——照舅"）等，考查理解和使用能力。\n\n【具体说明】\n① 惯用语：口语中短小定型的习惯用语，多为三字格。打头阵（率先行动）、开夜车（熬夜工作）、炒鱿鱼（辞退）、拍马屁（讨好奉承）、穿小鞋（暗中刁难）。特点：形象生动、口语色彩浓、含义不是字面意思。\n② 谚语：气象类（"朝霞不出门，晚霞行千里"）、农事类（"清明前后，种瓜点豆"）、哲理类（"路遥知马力，日久见人心"）、学习类（"书山有路勤为径，学海无涯苦作舟"）。\n③ 歇后语：谐音类（"外甥打灯笼——照舅(旧)"、"孔夫子搬家——净是书(输)"）、比喻类（"泥菩萨过江——自身难保"、"十五个吊桶打水——七上八下"）、故事类（"刘备借荆州——有借无还"）。\n④ 格言：有教育意义的精练语句——"学而不思则罔，思而不学则殆"、"生于忧患，死于安乐"、"业精于勤荒于嬉"。\n\n【常见错误】\n1. 惯用语理解字面化→"炒鱿鱼"不是真的炒菜\n2. 歇后语只知前不知后\n3. 谚语与格言混淆→谚语来自民间口头创作，格言出自名人之口\n\n【考试方向】\n选择题/填空题：补全歇后语、辨析惯用语含义、判断使用语境是否恰当。'
WHERE parent_id = @l3_ciyu AND name = '常用熟语与惯用语';

SELECT 'v129a: 词语运用 5个L4节点完成' AS progress;

-- ============================================================
-- 病句辨析与修辞（10个L4节点）parent: 病句辨析与修辞(L3)
-- ============================================================

SET @l3_bingju = (SELECT id FROM knowledge_nodes WHERE subject_id = 20 AND name = '病句辨析与修辞' AND level = 3 LIMIT 1);

UPDATE knowledge_nodes SET content =
'【一句话定义】\n语序不当指句子中词语的排列顺序不符合现代汉语表达习惯，导致表意不清或逻辑混乱。\n\n【具体说明】\n① 多层定语次序不当：正确顺序为"领属（谁的）+数量（多少）+性状（什么样的）+属性（什么性质的）+中心词"。越是本质性的定语越靠近中心词。\n② 多层状语次序不当：正确顺序为"条件/原因+时间+处所+范围/程度+情态+中心词"。\n③ 关联词位置不当：前后分句主语相同→关联词放主语后（"他不但学习好，而且体育好"）；主语不同→关联词放主语前（"不但他学习好，而且他妹妹学习也好"）。\n④ 定语和状语位置颠倒。\n\n【常见错误】\n1. 多重定语排列凭直觉→记住"领属+数量+性状+属性"顺序\n2. 关联词位置放错→不判断主语是否相同就放最前面\n\n【考试方向】\n选择题：选出"有/无语病的一项"，语序不当是最常见干扰项。'
WHERE parent_id = @l3_bingju AND name = '语序不当';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n搭配不当指句子中相邻成分在语法或语义上不能组合，是出现频率最高的病句类型。\n\n【具体说明】\n① 主谓搭配不当："他的写作水平有了明显增长"→"水平"不能说"增长"，改"提高"。\n② 动宾搭配不当："我们要养成讲卫生"→缺宾语中心词，改为"养成讲卫生的习惯"。\n③ 主宾搭配不当："北京的秋天是最美的季节"→主语"秋天"与宾语"季节"不一致（应改说完整）。\n④ 修饰语与中心语搭配不当："他有一双聪明能干的手"→"聪明"不能修饰"手"，改"灵巧"。\n⑤ 一面与两面搭配不当（重点陷阱）："学习成绩的提高取决于自身是否努力"→"提高"是一面，"是否"是两面，改为"成绩的好坏取决于自身是否努力"。常见两面词：是否、能否、成败、好坏、优劣、高低、有没有。\n\n【常见错误】\n1. "两面词"陷阱→句中出现了两面词就要检查前后是否都对应两面\n2. 动宾搭配不符合习惯→"解决问题"正确，"解决困难"不当（应是"克服困难"）\n3. 联合短语部分搭配不当→"克服了缺点和错误"只有"克服缺点"正确\n\n【考试方向】\n选择题：选出有/无语病的一项。搭配不当是出现频率最高的病句类型。'
WHERE parent_id = @l3_bingju AND name = '搭配不当';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n成分残缺指句子中缺少必要的语法成分（主语/谓语/宾语），成分赘余指出现了不必要的重复冗余。\n\n【具体说明】\n① 主语残缺（最常见）：介词淹没主语——"通过这次学习，使我提高了认识"→"通过"和"使"并用导致无主语，去掉其中一个。\n② 谓语残缺："我们一定要实现这个宏伟的目标，而奋斗"→缺少谓语，改为"而努力奋斗"。\n③ 宾语残缺："我们要积极响应"→缺宾语，补"学校的号召"。\n④ 成分赘余：词语重复——"目前的当务之急"（"当务之急"已含"目前"）、语义重复——"互相自我批评"（"自我"与"互相"矛盾）、虚词多余——"在大家的共同努力之下，使得问题得到解决"（去掉"使得"）。\n\n【常见错误】\n1. 滥用介词导致缺主语→"在…下""通过…""经过…"后面需要真正的主语\n2. 宾语较长时忘记收尾→看到长定语忘了检查有没有宾语中心词\n3. "当务之急""无数莘莘学子"等常见赘余→注意成语和固定搭配的本义\n\n【考试方向】\n选择题：选出有/无语病的一项。常隐藏在表面上通顺的句子中。'
WHERE parent_id = @l3_bingju AND name = '成分残缺或赘余';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n结构混乱指将两种不同的句式杂糅在一起，或一句话未说完又接上另一句话，导致句子结构不清晰。\n\n【具体说明】\n① 句式杂糅（最典型）："本着……为原则"→兼顾"本着……的原则"和"以……为原则"；"原因是……造成的"→兼顾"原因是……"和"是由……造成的"；"关键在于……起决定作用"→兼顾两个结构。\n② 中途易辙：一句话未说完另起一句——"中国人民自从接受了马克思主义之后，中国革命就在毛泽东领导下大大改了样子"→前句主语"中国人民"话没说完后句变成"中国革命"。\n③ 藕断丝连：把前一句的尾部用作后一句的开头——"我们向政府提意见是人民的责任"→改为"我们向政府提意见，这是人民的责任"。\n\n【常见错误】\n1. 高频杂糅句式要死记→"本着…的原则/以…为原则"、"原因是…/是由…造成的"\n2. 长句中夹杂两种结构→写到一半忘了原来的结构\n3. 口语习惯带入书面语→"原因是由于"口语化表达不规范\n\n【考试方向】\n选择题：选出有/无语病的一项。句式杂糅是中职考试的病句重点。'
WHERE parent_id = @l3_bingju AND name = '结构混乱';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n表意不明又称歧义句，指同一个句子可以有多种不同的理解方式，影响表达的准确性。\n\n【具体说明】\n① 多义词歧义："他走了一个多小时了"→"走"可以是"行走"或"离开"；"这饭不热了"→"热"可以是形容词（凉了）或动词（不用加热了）。\n② 结构歧义："咬死了猎人的狗"→可切分为①"咬死了/猎人的狗"（狗被咬死）或②"咬死了猎人的/狗"（狗咬死了猎人）；"三个学校的学生"→①三个/学校的学生（三所学校）或②三个学校的/学生（来自三个学校）。\n③ 指代不明："小明和小刚一起玩，他的书包掉了"→"他"指谁？\n④ 修饰关系不明："新职工的宿舍"→"新"修饰"职工"还是"宿舍"？\n\n【常见错误】\n1. 写句子时未注意"多义语感"→写的人觉得清楚读的人模糊\n2. 代词使用过于随意→前文出现多个人/物时，代词必须明确\n3. 数量词+名词的结构歧义→天生具有歧义可能\n\n【考试方向】\n选择题：选出"表意明确/有歧义的一项"。'
WHERE parent_id = @l3_bingju AND name = '表意不明（歧义句）';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n不合逻辑指句子虽然在语法结构上没有问题，但在事理逻辑上说不通。\n\n【具体说明】\n① 自相矛盾："整个大楼一片漆黑，只有一个房间亮着灯"→"一片漆黑"和"亮着灯"矛盾；"他是许多死难者中幸免的一个"→"死难者"和"幸免"矛盾。\n② 否定不当："我们一定要避免不发生事故"→"避免不发生"=要发生，改为"避免发生"。规律：双重否定=肯定，单重否定=否定，三重否定=单重否定。\n③ 主客颠倒："考试对我很熟悉"→应为"我对考试很熟悉"。\n④ 分类不当："我们买了苹果、香蕉和水果"→"水果"包含"苹果"和"香蕉"。\n⑤ 强加因果/条件："因为下雨了，所以今天是星期一"→无因果关系。\n\n【常见错误】\n1. 三重否定逻辑混乱→逐层分析："不能+否认+不是"="承认+是"\n2. "避免/防止/杜绝"后面再加否定→这些词本身是"不让发生"\n3. 并列项的包含关系→检查小概念是否被大概念包含\n\n【考试方向】\n选择题：选出有/无语病的一项。不合逻辑常与其他病句类型混合考查。'
WHERE parent_id = @l3_bingju AND name = '不合逻辑';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n比喻是用跟甲事物有相似点的乙事物来描写甲事物；借代是不直接说出事物名称而用相关事物代替。\n\n【具体说明】\n**比喻**：① 三要素：本体（被比喻）、喻体（用来比喻）、比喻词（像/如/仿佛/是/成了）。② 三种类型：明喻（本体+像+喻体·"月亮像圆盘"）、暗喻（本体+是+喻体·"月亮是圆盘"）、借喻（只出现喻体·"天上挂着一个圆盘"）。③ 作用：化抽象为具体、化陌生为熟悉。\n**借代**：① 类型：特征代本体（"红领巾"代少先队员）、部分代整体（"帆"代船）、具体代抽象（"枪杆子"代武装）。② 与借喻区别：借喻基于相似性（可还原为明喻），借代基于相关性（不能还原为明喻）。\n\n【常见错误】\n1. 暗喻与借喻混淆→暗喻有本体和喻体，借喻只有喻体\n2. 借喻与借代混淆→能否还原为明喻是判断关键\n3. 同类比较不是比喻→"他像他爸爸"（不是比喻）\n\n【考试方向】\n选择题选出"修辞手法与其他三项不同的一项"或判断手法类型。'
WHERE parent_id = @l3_bingju AND name = '比喻与借代';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n拟人是把事物当作人来写，赋予事物人的动作和情感；夸张是对事物的特征故意夸大或缩小。\n\n【具体说明】\n**拟人**：① 形式：把事物当人来叙述（"太阳露出了笑脸"）、赋予事物人的情感（"花儿在风中跳舞"）、让事物说话（"油蛉在这里低唱，蟋蟀们在这里弹琴"）。② 作用：生动形象、赋予情感色彩、增强感染力。③ 与比喻区别：比喻重在"比"（相似），拟人重在"拟"（当作）。\n**夸张**：① 三种类型：扩大夸张（"飞流直下三千尺"）、缩小夸张（"五岭逶迤腾细浪"）、超前夸张（"他酒还没喝，脸就红了"）。② 作用：突出特征、增强感染力。③ 注意：夸张不是浮夸，要有现实基础；科学说明文和公文不能用夸张。\n\n【常见错误】\n1. 拟人与比喻混淆→拟人是"当作人"，比喻是"像"\n2. 夸张与修辞效果混淆→夸张是故意"言过其实"\n3. "白发三千丈"→需能辨认是扩大夸张\n\n【考试方向】\n选择题判断修辞手法，常与比喻混合考查。'
WHERE parent_id = @l3_bingju AND name = '拟人与夸张';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n排比是把三个或以上结构相同的语句排列起来；对偶是用字数相等、结构相同的两个语句表达相关或相反的意思。\n\n【具体说明】\n**排比**：① 特点：三个或以上结构相似、语气一致、意义相关的语句。② 作用：增强语势、强调内容、加深印象、条理分明。③ 形式：并列排比（多角度并列）、递进排比（层层深入）。\n**对偶**：① 特点：字数相等、结构相同、意义相关的两个语句。② 三种类型：正对（上下联内容相近·"海内存知己，天涯若比邻"）、反对（上下联内容相反·"横眉冷对千夫指，俯首甘为孺子牛"）、串对/流水对（上下联有因果/条件关系·"欲穷千里目，更上一层楼"）。③ 与排比区别：对偶是两个（一对），排比是三个或以上。\n\n【常见错误】\n1. 排比与反复混淆→排比结构相似内容不同，反复相同语句重复\n2. 对偶与对比混淆→对偶重形式，对比重内容\n3. 两个语句结构相似不是对偶→必须字数相等、结构相同\n\n【考试方向】\n选择题判断修辞手法或选出没有使用对偶/排比的选项。'
WHERE parent_id = @l3_bingju AND name = '排比与对偶';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n设问是自问自答以引起注意和思考；反问是答案已在问句中以加强语气；反复是反复使用相同词语或句子以突出强调。\n\n【具体说明】\n**设问**：① 特征：无疑而问、自问自答——"谁是最可爱的人呢？我们的战士。"② 作用：引起读者注意和思考、承上启下过渡、使文章有波澜。\n**反问**：① 特征：答案在问句中不需要回答——"难道我们不应该努力学习吗？"=应该努力学习；"这么简单的道理，谁不知道呢？"=谁都知道。② 作用：加强语气、增强说服力。③ 与设问区别：设问自问自答，反问不需回答。\n**反复**：① 类型：连续反复（"盼望着，盼望着"）、间隔反复（同一语句间隔出现）。② 作用：突出强调、增强节奏感。③ 与排比区别：反复是相同语句重复，排比是结构相似内容不同。\n\n【常见错误】\n1. 设问与反问混淆→设问后面有答案，反问没有\n2. 反复与排比混淆→反复"同句重复"，排比"结构相似内容不同"\n3. 反问中否定不当→"难道我们不能否认吗？"三重否定混乱\n\n【考试方向】\n选择题选出"修辞手法与其他三项不同的"或判断手法类型。'
WHERE parent_id = @l3_bingju AND name = '设问、反问与反复';

SELECT 'v129a: 病句辨析与修辞 10个L4节点完成！Part1 全部23个节点填充完毕' AS result;
